import {
  afterAll,
  beforeAll,
  beforeEach,
  describe,
  it,
  expect,
  vi,
} from "vitest";
import { randomUUID } from "node:crypto";
import { boundary, usageFixture, usageOwner } from "./fixtures/usage-worker";
import { databaseTestsEnabled } from "./helpers/foundation-db";
const blob = vi.hoisted(() => ({ get: vi.fn(), del: vi.fn() }));
vi.mock("@vercel/blob", () => ({
  get: blob.get,
  del: blob.del,
  list: vi.fn(),
}));
import { activateResume, discardUnactivatedResume } from "@/lib/storage";
function pdf() {
  return {
    statusCode: 200,
    stream: new ReadableStream({
      start(c) {
        c.enqueue(new TextEncoder().encode("%PDF-1.7 fixture"));
        c.close();
      },
    }),
  };
}
describe.runIf(databaseTestsEnabled)(
  "suspension and upload activation ordering",
  () => {
    let fixture: Awaited<ReturnType<typeof usageFixture>>;
    beforeAll(async () => {
      fixture = await usageFixture();
    });
    beforeEach(() => {
      vi.stubEnv("BLOB_READ_WRITE_TOKEN", "fake-test-token");
      blob.get.mockReset().mockImplementation(async () => pdf());
      blob.del.mockReset().mockResolvedValue(undefined);
    });
    afterAll(async () => {
      vi.unstubAllEnvs();
      await fixture?.close();
    });
    it("rejects activation crossing suspension, retires the path, and never deletes an existing resume", async () => {
      const f = await usageOwner(boundary.db),
        path = `resumes/${f.user.id}/${randomUUID()}.pdf`;
      let ready!: () => void, finish!: () => void;
      const entered = new Promise<void>((r) => {
          ready = r;
        }),
        release = new Promise<void>((r) => {
          finish = r;
        });
      blob.get.mockImplementationOnce(async () => {
        ready();
        await release;
        return pdf();
      });
      const activation = activateResume(f.user.id, path, "resume.pdf");
      const rejected = expect(activation).rejects.toThrow("unavailable");
      await entered;
      await boundary.db.$transaction(async (tx) => {
        await tx.$queryRaw`SELECT id FROM "User" WHERE id=${f.user.id} FOR UPDATE`;
        await tx.user.update({
          where: { id: f.user.id },
          data: {
            isSuspended: true,
            suspendedAt: new Date(),
            suspensionReason: "SECURITY",
          },
        });
      });
      finish();
      await rejected;
      const tombstone = await boundary.db.attachment.findFirstOrThrow({
        where: { userId: f.user.id, storagePath: path },
      });
      expect(tombstone.rejectedAt).toBeInstanceOf(Date);
      expect(blob.del).toHaveBeenCalledWith(path, expect.anything());
      await boundary.db.user.update({
        where: { id: f.user.id },
        data: { isSuspended: false, suspendedAt: null, suspensionReason: null },
      });
      await expect(
        activateResume(f.user.id, path, "resume.pdf"),
      ).rejects.toThrow("removed");
      const retainedPath = `resumes/${f.user.id}/${randomUUID()}.pdf`;
      await activateResume(f.user.id, retainedPath, "retained.pdf");
      blob.del.mockClear();
      await boundary.db.user.update({
        where: { id: f.user.id },
        data: {
          isSuspended: true,
          suspendedAt: new Date(),
          suspensionReason: "SECURITY",
        },
      });
      await discardUnactivatedResume(f.user.id, retainedPath, new Date());
      expect(blob.del).not.toHaveBeenCalled();
      expect(
        (await boundary.db.user.findUniqueOrThrow({ where: { id: f.user.id } }))
          .currentAttachmentId,
      ).not.toBeNull();
    });
    it("retains a durable rejection and retries physical cleanup after a Blob failure", async () => {
      const f = await usageOwner(boundary.db),
        path = `resumes/${f.user.id}/${randomUUID()}.pdf`;
      await boundary.db.user.update({
        where: { id: f.user.id },
        data: {
          isSuspended: true,
          suspendedAt: new Date(),
          suspensionReason: "SECURITY",
        },
      });
      blob.del.mockRejectedValueOnce(new Error("FAKE-BLOB-OUTAGE"));
      await expect(
        discardUnactivatedResume(f.user.id, path, new Date()),
      ).rejects.toThrow("FAKE-BLOB-OUTAGE");
      expect(
        (
          await boundary.db.attachment.findFirstOrThrow({
            where: { userId: f.user.id, storagePath: path },
          })
        ).storageDeletedAt,
      ).toBeNull();
      await discardUnactivatedResume(f.user.id, path, new Date());
      expect(
        (
          await boundary.db.attachment.findFirstOrThrow({
            where: { userId: f.user.id, storagePath: path },
          })
        ).storageDeletedAt,
      ).toBeInstanceOf(Date);
    });
  },
);
